package edu.klu.foodwaste.web;
import edu.klu.foodwaste.model.*;import edu.klu.foodwaste.repo.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/feedback") public class FeedbackController{
 private final FeedbackRepository feedback;private final MealRepository meals;private final UserRepository users;public FeedbackController(FeedbackRepository f,MealRepository m,UserRepository u){feedback=f;meals=m;users=u;}
 @GetMapping public List<Map<String,Object>> all(){return feedback.findAll().stream().sorted(Comparator.comparing(Feedback::getCreatedAt).reversed()).map(this::dto).toList();}
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object> b,Authentication a){if(a==null)return ResponseEntity.status(401).body(Map.of("message","Please log in"));try{long mealId=Long.parseLong(b.get("mealId").toString());int rating=Integer.parseInt(b.get("rating").toString());if(rating<1||rating>5)return ResponseEntity.badRequest().body(Map.of("message","Rating must be 1–5"));Meal m=meals.findById(mealId).orElse(null);if(m==null)return ResponseEntity.badRequest().body(Map.of("message","Meal not found"));Feedback f=new Feedback();f.setMeal(m);f.setUser(users.findByEmail(a.getName()).orElseThrow());f.setRating(rating);f.setComment(Objects.toString(b.getOrDefault("comment","")));return ResponseEntity.status(201).body(dto(feedback.save(f)));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Provide valid mealId and rating"));}}
 private Map<String,Object> dto(Feedback f){return Map.of("id",f.getId(),"mealId",f.getMeal().getId(),"mealName",f.getMeal().getName(),"userName",f.getUser().getName(),"rating",f.getRating(),"comment",f.getComment()==null?"":f.getComment(),"createdAt",f.getCreatedAt());}
}
